"""Build the private-review portfolio. Python stdlib; no runtime dependencies."""
from pathlib import Path
import html,json,re,shutil,datetime
import components as B
ROOT=Path(__file__).parent
D=json.loads((ROOT/'content/site.json').read_text())
P=json.loads((ROOT/'content/projects.json').read_text())
P['projects']=[p for p in P['projects'] if p.get('visible_on_site') is True]
P['categories']=list(dict.fromkeys(p['category'] for p in P['projects']))
C=[c for c in json.loads((ROOT/'content/certifications.json').read_text()) if c.get('credential_url')]
OUT=ROOT/'dist'
# Only generated files enter the served directory. Private evidence stays outside it.
if OUT.exists():shutil.rmtree(OUT)
OUT.mkdir();shutil.copytree(ROOT/'assets',OUT/'assets')
for item in D['downloads'].values():
 if item.get('public_approved') is True:
  source=ROOT/'private/original-pdfs'/Path(item['path']).name
  if not source.is_file():raise FileNotFoundError(source)
  target=OUT/item['path'].lstrip('/');target.parent.mkdir(exist_ok=True);shutil.copy2(source,target)
e=B.e;button=B.button;section=B.section;heading=B.heading;enquiry=B.enquiry
NAV=[('Home','/'),('Services','/services/'),('Projects & Research','/projects/'),('About','/about/'),('How I Work','/how-i-work/'),('Certifications & Education','/certifications/'),('Research Tools & Skills','/skills/'),('AI Evaluation','/ai-evaluation/'),('Contact','/contact/')]
def nav(active):
 def link(label,url):return f'<a href="{url}"'+(' aria-current="page"' if active==label else '')+f'>{e(label)}</a>'
 return '<a class="skip" href="#main">Skip to content</a><header class="header"><div class="wrap nav"><a class="brand" href="/" aria-label="Asif Hussain home"><span class="monogram" aria-hidden="true">AH</span><span><strong>Asif Hussain</strong><small>Economics · Data · Research</small></span></a><button class="menu" type="button" aria-controls="navlinks" aria-expanded="false">Menu</button><nav id="navlinks" class="navlinks" aria-label="Main navigation">'+''.join(link(*pair) for pair in NAV[:4])+'<details class="nav-more"><summary'+(' class="current"' if active in [x[0] for x in NAV[4:8]] else '')+'>More</summary><div>'+''.join(link(*pair) for pair in NAV[4:8])+'</div></details>'+button('Let’s Work Together','/contact/')+'</nav></div></header>'
def write(path,title,desc,body,active):
 folder=OUT/path;folder.mkdir(parents=True,exist_ok=True)
 footer='<footer class="footer"><div class="wrap"><div class="footer-top"><div><span class="monogram" aria-hidden="true">AH</span><h3>Asif Hussain</h3><p>Economics Researcher | Research Consultant | Data Analyst</p><a href="mailto:'+e(D['email'])+'">'+e(D['email'])+'</a></div><nav aria-label="Footer navigation">'+''.join(f'<a href="{u}">{e(n)}</a>' for n,u in NAV[1:])+'</nav></div><div class="footer-inner"><span>© '+str(datetime.date.today().year)+' Asif Hussain · Pakistan · Remote collaboration</span><a href="'+e(D['linkedin'])+'" target="_blank" rel="noopener noreferrer">Connect on LinkedIn →</a><span>Independent research support · Remote international collaboration</span></div></div></footer>'
 (folder/'index.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="index,follow"><meta name="theme-color" content="#142638"><title>'+e(title)+' | Asif Hussain</title><meta name="description" content="'+e(desc)+'"><link rel="canonical" href="'+e(D['site_url'].rstrip('/')+'/'+str(path).strip('.').strip('/')+('/' if str(path)!='.' else ''))+'"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/site.css"><script src="/assets/site.js" defer></script></head><body>'+nav(active)+'<main id="main">'+body+'</main>'+footer+'</body></html>')
def pagehero(label,title,desc,meta=[]):return B.page_hero(label,title,desc,meta)
def cta():return section('discuss','<div class="closing-cta"><div class="eyebrow">A useful next step</div><h2>Have a research question, dataset, or report that needs careful analysis?</h2>'+button('Discuss Your Project','/contact/')+'</div>')
def hero():
 art=re.search(r'(<div class="hero-art".*?</p></div>)',B.hero()).group(1).replace('class="hero-art"','class="hero-art animated-art"').replace('Research → Clarity','Research notebook').replace('AH / 01','AH / Field notes').replace('Evidence → insight','Question → evidence')
 return '<div class="hero journal-hero"><div class="wrap"><div class="hero-grid"><div><div class="eyebrow">Independent research · Economic analysis</div><p class="hero-name">Asif Hussain <span> / Pakistan · Remote</span></p><h1>Economic research.<br>Clear analysis.<br><em>Useful insights.</em></h1><p class="intro">'+e(D['introduction'])+'</p><div class="actions">'+button('Discuss a Project','/contact/')+button('Explore Selected Work','/projects/',True)+'</div><p class="remote"><span class="dot"></span>MPhil Economics · Research Associate since 2022</p></div>'+art+'</div><div class="hero-strip"><span>Economic & policy evidence</span><span>Documented analysis</span><span>Methodology review</span><span>Clear research reporting</span></div></div></div>'

def capabilities():
 items=[('economic-research','Economic & Policy Research','A clear evidence base for a defined economic question.','Referenced research brief · Comparative indicator tables · Findings and limitations'),('statistical-analysis','Quantitative Research Support','From an existing dataset to an analysis you can explain.','Documented data preparation · Statistical tables · Interpretation and agreed scripts'),('research-review','Research Quality Review','An independent reading of methods, numbers and conclusions.','Annotated report · Evidence-to-claim checks · Prioritised revision notes')]
 body=heading('01 / Research support','Defined questions.<br>Reviewable deliverables.','For consultancies, policy organisations and independent consultants who need additional research and analytical capacity.')+'<div class="capability-grid focused-capabilities">'
 for i,(slug,title,desc,outputs) in enumerate(items,1):body+='<article><span class="number">'+f'{i:02}'+'</span><h3>'+title+'</h3><p>'+desc+'</p><p class="deliverable-line"><strong>Typical outputs</strong><br>'+outputs+'</p><a class="text-link" href="/services/'+slug+'/">Discuss the scope →</a></article>'
 return section('capabilities',body+'</div>')

def card(p):
 typ='sample' if p.get('supported_sample') else 'review' if p['category']==P['categories'][4] else 'research'
 visual=f'<div class="project-cover {typ}" aria-hidden="true"><span>{"Source-backed sample" if p.get("supported_sample") else "Review inventory" if typ=="review" else "Research inventory"}</span><div class="cover-symbol">{ "∑" if typ=="sample" else "↔" if typ=="review" else "AH"}</div><span>{e(p["project_type"])}</span></div>'
 if p.get('supported_sample'):
  previews={'south-asia':'<span>Real GDP per capita growth · 2010–2024</span><div class="sample-bars"><div><span>Pakistan</span><i><b style="width:28.48%"></b></i><span>30.11%</span></div><div><span>Bangladesh</span><i><b style="width:100%"></b></i><span>105.72%</span></div><div><span>India</span><i><b style="width:86.66%"></b></i><span>91.62%</span></div></div>', 'health-statistics':'<span>Reported BMI comparison</span><div class="preview-stat">0.365 <small>female-minus-male difference</small></div><span>95% CI −0.198 to 0.928 · p = 0.203</span>', 'retail-analysis':'<span>Sales per reported record</span><div class="preview-comparison"><strong>246.51<small>Mean</small></strong><strong>85.00<small>Median</small></strong></div><span>Reported units · Currency unspecified</span>'}
  visual='<div class="project-cover sample" aria-hidden="true">'+previews[p['slug']]+'</div>'
 return '<article class="project project-card" data-project data-category="'+e(p['category'])+'" data-search="'+e(' '.join([p['title'],p['category'],p['summary'],' '.join(p['methods']),' '.join(p['tools'])]).lower())+'" data-evidence="'+('supported' if p.get('supported_sample') or p['id'] in ['p01','p02'] else 'pending')+'"><a class="cover-link" href="/work/'+p['slug']+'/" tabindex="-1" aria-hidden="true">'+visual+'</a><div class="card-body"><div class="card-meta"><span class="status '+('ongoing' if p['status']=='Ongoing Research' else '')+'">'+e(p['display_status'])+'</span>'+('<span class="featured-tag">Featured</span>' if p['featured'] else '')+'</div><span class="category-label">'+e(p['category'])+'</span><h3><a href="/work/'+p['slug']+'/">'+e(p['title'])+'</a></h3><p>'+e(p['summary'])+'</p><a class="text-link" href="/work/'+p['slug']+'/">'+('Read case study' if p.get('supported_sample') else 'View research record')+' →</a></div></article>'
def cardgrid(items):return '<div class="projects library-grid">'+''.join(card(p) for p in items)+'</div>'
def featured():
 return section('work',heading('02 / Selected analytical work','Evidence you can inspect.','Three supported samples show the questions, methods, interpretation and limitations. They are demonstrations or revised analysis samples—not claims of commissioned client outcomes.')+cardgrid(P['projects'])+'<div class="actions">'+button('Read the Case Studies','/projects/',True)+'</div>')

def library():
 body=heading('Selected case studies','The analysis, in context.','Each sample explains what is supported by the supplied evidence and what would require the original data or further investigation.')+cardgrid(P['projects'])
 body+='<div class="notice"><strong>How to read these samples</strong>The public-data demonstration and revised statistical/business samples are distinct from paid client assignments. Original data and scripts are not available for independent replication. Reports are not offered for download without sharing approval.</div>'
 return section('project-library',body)

def insights():
 charts=B.south_charts();figures=re.findall(r'<figure.*?</figure>',charts);table=charts[charts.index('<div class="table-scroll">'):]
 body=heading('03 / Data insights','Growth and employment,<br>read separately.','Verified endpoint summaries for Pakistan, Bangladesh and India. Explore the two measures without inferring causality.')
 body+='<div class="insight-controls"><div class="chart-tabs" role="group" aria-label="Choose economic indicator"><button class="chart-tab" type="button" data-chart-tab="growth" aria-pressed="true">Real GDP per capita growth</button><button class="chart-tab" type="button" data-chart-tab="employment" aria-pressed="false">Women’s employment</button></div><div><label for="insight-country">Country detail</label><select id="insight-country">'+''.join('<option value="'+e(r['country'])+'">'+e(r['country'])+'</option>' for r in D['south_asia'])+'</select></div></div>'
 body+='<div data-chart-panel="growth">'+figures[0]+'</div><div data-chart-panel="employment">'+figures[1]+'</div><p class="insight-detail" id="insight-detail" role="status" aria-live="polite"></p>'+table+'<p class="small">Method: supplied 2010/2024 endpoint comparison; employment changes are percentage points. No interpolated annual observations. Sources and interpretation limits are explained in the <a href="/work/south-asia/">full case study</a>.</p>'
 return section('insights',body)
def intro():return section('introduction','<div class="intro-editorial"><div><div class="eyebrow">An economist’s perspective</div><h2>Careful work,<br>clearly explained.</h2></div><div><p>I am Asif Hussain, an economics researcher with BS and MPhil qualifications and research consultancy experience since 2022.</p><p>My work brings together quantitative research, economic data analysis, statistical interpretation, research reporting and data visualisation. Research quality review adds a second question: does the conclusion follow from the evidence?</p><a class="text-link" href="/about/">Explore my background →</a></div></div>')
def qualifications_preview():
 return section('qualifications','<div class="intro-editorial"><div><div class="eyebrow">Professional background</div><h2>Grounded in economics.<br>Focused on clear evidence.</h2></div><div><p><strong>MPhil Economics</strong> · Bahauddin Zakariya University, 2022–2024.<br><strong>BS Economics</strong> · University of Sargodha, 2017–2021.</p><p>Remote Research Associate at ZAR Management Consultancies since 2022. Formal employment is separate from independent research and portfolio demonstrations.</p><div class="actions">'+button('View Professional Profile','/profile/',True)+'</div><a class="text-link" href="/certifications/">Education & continuing professional development →</a></div></div>')

def services():
 body=heading('Services','Support that begins<br>with the question.','Each engagement is scoped to the evidence, required expertise and intended decision.')
 for i,s in enumerate(D['services'],1):body+='<article class="service-row" id="'+s['id']+'"><span class="number">'+f'{i:02}'+'</span><div><h3><a href="/services/'+s['id']+'/">'+e(s['name'])+'</a></h3><p>'+e(s['summary'])+'</p></div><p>'+e(s['deliverables'])+'</p><a class="text-link" href="/services/'+s['id']+'/">View scope →</a></article>'
 # Preserve former service anchor and enquiry compatibility.
 body+='<div id="data-preparation" class="notice"><strong>Data preparation</strong>Cleaning, validation and documentation are part of <a href="/services/statistical-analysis/">Statistical Analysis & Econometrics</a>.</div>'
 return section('services',body)
def service_page(s):
 body='<div class="service-detail"><div><h2>Who this is for</h2><p>'+e(s['audience'])+'</p><h3>The practical problem</h3><p>'+e(s['problem'])+'</p>'+button('Enquire About This Service',enquiry(s['id']))+'</div><div><h2>What I can do</h2><ul>'+''.join('<li>'+e(a)+'</li>' for a in s['activities'])+'</ul><h3>Expected deliverables</h3><p>'+e(s['deliverables'])+'</p><h3>What you provide</h3><p>'+e(s['requirements'])+'</p><h3>Applicable tools and approach</h3><p>'+e(s['tools'])+'</p><div class="notice"><strong>Scope and limitations</strong>'+e(s['limitations'])+'</div></div></div>'
 return section('service-scope',body)+B.paid()+cta()
def experience():return '<article class="experience-card"><div><span class="eyebrow">Formal employment</span><h3>Research Associate</h3><strong>ZAR Management Consultancies</strong><p>Dubai, UAE · Remote from Pakistan<br>2022–Present</p></div><ul><li>Economic, financial and socioeconomic research using recognised secondary sources.</li><li>Dataset preparation, cleaning, organisation and analysis.</li><li>Statistical interpretation and econometric research using Stata and Excel.</li><li>Analytical reports, tables, charts, dashboards and presentations.</li><li>Review of methods, data limitations and quantitative findings where relevant to actual assignments.</li><li>Clear communication of complex research findings.</li></ul></article>'
def about():
 body='<div class="about-grid"><div><div class="eyebrow">Background</div><h2>Economics at the core.<br>Evidence throughout.</h2><p>'+e(D['bio'])+'</p><p>I have also undertaken independent and academic work involving econometrics, statistical modelling, survey analysis, financial analysis and critical assessment of technical research. The selected samples are separate from my employment and explain the available evidence and the limits of my contribution explicitly.</p><a class="text-link" href="/skills/">Research tools & methods →</a></div><div class="timeline">'
 for date,t,desc in [('2017–2021','BS Economics','University of Sargodha, Pakistan'),('2022–2024','MPhil Economics','Bahauddin Zakariya University, Multan, Pakistan'),('2022–Present','Research Associate','ZAR Management Consultancies · Remote from Pakistan'),('Ongoing','Inclusive Growth Index research collaboration','With Dr Dragana Radicic, University of Lincoln. Research collaboration, not university employment or endorsement.')]:body+='<article><small>'+date+'</small><h3>'+t+'</h3><p>'+desc+'</p></article>'
 body+='</div></div>'+experience()+'<div class="notice"><strong>Professional development</strong>Training topics include Google data analytics, advanced analytics, business intelligence and AI, along with sustainable development, infrastructure finance and digital economies. <a href="/certifications/">View qualifications and evidence notes →</a></div>'
 return section('about',body)+cta()
def certifications():
 cats=list(dict.fromkeys(c['category'] for c in C))
 body='<div class="education-grid"><article><div class="eyebrow">2022–2024</div><h2>MPhil Economics</h2><p>Bahauddin Zakariya University<br>Multan, Pakistan</p><p class="small">Research on e-commerce, employment and inclusive growth across 20 developing countries.</p></article><article><div class="eyebrow">2017–2021</div><h2>BS Economics</h2><p>University of Sargodha<br>Pakistan</p><p class="small">Economics education and quantitative research foundations.</p></article></div><div class="notice"><strong>Training, with transparent evidence</strong>Dates and credential links below are supplied by Asif Hussain. No external verification badge is implied. Exact dates are shown only when supplied. Certificate files have not been supplied for this website. Training is distinct from professional employment.</div><div class="credential-filters" role="group" aria-label="Filter training credentials"><button type="button" data-cert-filter="all" aria-pressed="true">All training</button>'+''.join('<button type="button" data-cert-filter="'+e(c)+'" aria-pressed="false">'+e(c)+'</button>' for c in cats)+'</div><p class="small" id="cert-count" role="status" aria-live="polite">'+str(len(C))+' training records</p><div class="credential-grid">'
 for c in C:
  date=datetime.date.fromisoformat(c['date']).strftime('%d %B %Y') if len(c['date'])==10 else c['date']+' · year supplied'
  body+='<article class="credential" data-cert-category="'+e(c['category'])+'"><span class="category-label">'+e(c['issuer'])+'</span><h3>'+e(c['name'])+'</h3><p class="credential-date">'+date+'</p><p>'+e(c['description'])+'</p>'+('<a class="text-link" target="_blank" rel="noopener noreferrer" href="'+e(c['credential_url'])+'">View Credential →</a>' if c['credential_url'] else '<span class="small">Verification link not supplied</span>')+'<details><summary>Evidence note</summary><p>'+e(c['evidence'])+'</p></details></article>'
 body+='</div><p class="small">Additional training records remain in the private content archive until supporting documentation is available. No transcripts, CGPAs, educational identifiers or private CV contacts are exposed.</p>'
 return section('certifications',body)
def skills():
 body='<div class="skills-grid"><article><div class="eyebrow">Primary professional tools</div><h2>Stata.<br>Microsoft Excel.</h2><p>Econometric research, dataset preparation, statistical interpretation and analytical reporting within the agreed scope.</p></article><article><div class="eyebrow">Additional experience & training</div><h2>Tools for the task.</h2><div class="tool-tags">'+''.join('<span>'+e(t)+'</span>' for t in D['working_tools'])+'</div><p>Practical experience and training vary by tool. The expertise required for a specialist assignment is confirmed before the work is accepted.</p></article></div><h2 class="collection-title">Methods & competencies</h2><div class="method-list">'+''.join('<span>'+m+'</span>' for m in ['Descriptive statistics','Data cleaning','Correlation & hypothesis testing','Regression analysis','Panel-data econometrics','Statistical interpretation','Data visualisation','Research documentation','Evidence synthesis','Research quality assurance','Technical report review'])+'</div><div class="notice"><strong>Evidence-based proficiency</strong>The supplied CV documents fixed-effects, random-effects and GMM methods in MPhil research. Google credentials document training, including Python and machine-learning foundations; they do not imply advanced engineering, cloud architecture or specialist ML employment.</div>'
 return section('skills',body)+cta()
def ai_page():
 return section('ai-reviews','<div class="intro-editorial"><div><div class="eyebrow">Supporting service</div><h2>Review the reasoning.<br>Check the evidence.</h2></div><div><p>I offer research quality review for analytical documents, including AI-assisted economic reports, technical summaries, slide decks and charts.</p><p>The review can examine whether sources are traceable, numbers are consistent, methods are appropriate and conclusions are supported by the available evidence.</p><p>This is both an available service and an area of professional interest. It does not imply AI-lab employment, completed AI-training contracts or formal journal peer-review appointments.</p>'+button('Discuss a Document Review',enquiry('ai-evaluation'))+'</div></div><div class="notice"><strong>A defined review scope</strong>Agree the document, available source materials, evaluation criteria and expected output before work begins. Typical outputs include an annotated document and a prioritised issue log. Specialist clinical, legal, engineering or cybersecurity verification may require a qualified domain expert.</div>')+cta()

def how():
 terms='<div class="principles"><article><h3>A written scope</h3><p>Agree on the question, evidence, deliverables, file formats and intended audience before work begins.</p></article><article><h3>Clear project terms</h3><p>Confirm fees, payment terms, timeline, revision scope, confidentiality and communication arrangements in advance.</p></article><article><h3>Transparent findings</h3><p>Document sources and relevant limitations. Discuss data access, secure sharing and permitted AI use before handling material.</p></article></div>'
 pilot='<div class="trial-grid"><div><div class="eyebrow">Start with a defined engagement</div><h2>A scoped pilot.<br>A practical first step.</h2><p>For a substantial assignment, we can first agree a small paid pilot with a specific question, deliverable, fee and delivery date. Review the output before deciding on further work.</p>'+button('Discuss a Paid Pilot',enquiry())+'</div><div><h3>What we agree first</h3><ul><li>Question and source materials</li><li>One reviewable output and delivery format</li><li>Fee, payment terms and timeline</li><li>Review criteria and included revisions</li><li>Confidentiality and communication arrangements</li></ul><p class="small">No automatic subscription or obligation to continue.</p></div></div>'
 trial='<details class="optional-trial"><summary>Is a small introductory free trial available?</summary><p>A limited free trial may be agreed before a larger engagement: one task per prospective client, at most three hours, one deliverable, public or authorised data only, and an agreed scope and date. There is no payment requirement or obligation to continue. Larger projects, specialist analyses and ongoing assignments are paid engagements.</p><a class="text-link" href="'+enquiry(kind='trial')+'">Discuss a limited trial →</a></details>'
 return B.workflow()+section('research-principles',terms)+section('pilot',pilot)+B.paid()+section('optional-trial',trial)+B.faq()

def contact():
 markup=B.contact().replace('Project description *','Project overview *').replace('Prepare Email Enquiry','Send Project Enquiry').replace('This form prepares an email draft for your email app.', '“Send Project Enquiry” prepares a mailto draft; your email application opens when you choose “Open Email Draft”.')
 fields='<div class="field full"><label for="deliverable">Expected deliverable *</label><input id="deliverable" name="deliverable" maxlength="300" required><span class="field-error" id="deliverable-error"></span></div><div class="field full"><label for="reference">File or reference link <span class="small">(optional; public or authorised only)</span></label><input id="reference" name="reference" type="url" maxlength="600" placeholder="https://" aria-describedby="reference-error"><span class="field-error" id="reference-error"></span></div>'
 markup=markup.replace('<div class="field"><label for="deadline">',fields+'<div class="field"><label for="deadline">')
 markup=markup.replace('<p>Based in Pakistan<br>Remote collaboration with international clients</p>','<p>Based in Pakistan<br>Remote collaboration with international clients</p>'+button('Email Directly','mailto:'+D['email'],True))
 return markup

def project_page(p):
 hero=pagehero(p['project_type'],e(p['title']),e(p['summary']),[('Research domain',p['category']),('Classification',p['display_status']),('Evidence',p['evidence']),('Coverage',p['dates'])])
 note='<div class="evidence-banner"><span class="status">'+e(p['display_status'])+'</span><p>'+('A sample supported by the supplied documentation, with the contribution and limits to replication explained below.' if p.get('supported_sample') or p['id'] in ['p01','p02'] else 'Project documentation being prepared. This record is an unverified inventory item, not a claim of a completed or publicly approved assignment.')+'</p></div>'
 if p.get('supported_sample'):
  content={'south-asia':B.south,'health-statistics':B.health,'retail-analysis':B.retail}[p['slug']]
  main=B.case(note+case_brief(p)+content)
 else:
  verified=p['id'] in ['p01','p02']
  methods=', '.join(p['methods']) or 'Project documentation being prepared.'
  label='Documented methods' if p.get('methods_verified') else 'Inventory topics — implementation not verified'
  body=note+'<h2 id="overview">Background and research objective</h2><p>'+e(p['research_question'])+'</p><p>'+('This is academic research, separate from the Research Associate employment record.' if p['id']=='p01' else 'Ongoing independent research collaboration, distinct from university employment or endorsement.' if p['id']=='p02' else 'The user-supplied inventory identifies this topic. A completed output is needed before research conclusions, project completion or specific responsibilities can be verified.')+'</p><h2 id="evidence">Contribution, data and methods</h2><h3>My role and contribution</h3><p>'+e(p['contribution'])+'</p><div class="table-scroll"><table><caption>Evidence record</caption><tbody>'
  for k,v in [('Dataset and source',', '.join(p['data_sources']) or 'Not confirmed from source files'),('Geographic coverage',p['coverage']),('Temporal coverage',p['dates']),('Software documented',', '.join(p['tools']) or 'Not confirmed'),(label,methods)]:body+='<tr><th scope="row">'+e(k)+'</th><td>'+e(v)+'</td></tr>'
  body+='</tbody></table></div><h3>Analytical workflow</h3><p>'+('The supplied CV documents panel construction and fixed-effects, random-effects and GMM estimation. The full thesis is needed to inspect indicator selection, diagnostics and inference.' if p['id']=='p01' else 'The supplied CV documents literature review, indicator identification, international-data organisation and development of an empirical framework. Final weighting and sensitivity results are not supplied.' if p['id']=='p02' else 'Research question → analytical method → evidence checked → issues identified → suggested improvements. Completed review notes or analysis files are required before this workflow can be attributed to this item.')+'</p><h2 id="findings">Verified findings and interpretation</h2>'+(''.join('<p>'+e(f)+'</p>' for f in p['verified_findings']) if p['verified_findings'] else '<p>Project documentation being prepared.</p><p>No unverified numerical findings, project screenshots or results charts are displayed.</p>')+'<h2 id="limitations">Limitations and uncertainties</h2><ul>'+''.join('<li>'+e(l)+'</li>' for l in p['limitations'])+'</ul><h3>Reproducibility</h3><p>Original data, code and a completed report are needed for an independent rerun or evidence audit. No independent replication is claimed.</p><h2 id="contribution">Source material and sharing</h2><p>No public download is approved for this record. Source manuscripts, contributions and publication permissions must be confirmed before materials are released.</p>'
  main=B.case(body)
 related=[q for q in P['projects'] if q['category']==p['category'] and q['slug']!=p['slug']][:3]
 if not related:related=[q for q in P['projects'] if q.get('supported_sample')][:3]
 return hero+main+section('related',heading('Continue exploring','Related analytical samples.')+cardgrid(related))
def case_brief(p):
 briefs={
 'south-asia':('Compare economic growth and women’s employment without confusing coincidence with causality.','Descriptive endpoint comparison of Pakistan, Bangladesh and India, 2010–2024.','A country comparison table, a real GDP per capita growth chart, an employment comparison chart and an interpretation note.','Growth and women’s employment should be reported separately; the supplied changes do not establish a causal link.'),
 'health-statistics':('Explain supplied statistical results without overstating what they mean.','Revision and interpretation of existing outputs; no independent rerun.','Sample summary, BMI comparison, regression table and methodological limitations.','Interpret the statistical evidence carefully, acknowledge uncertainty and avoid interpreting the direction of the sex coefficient until the variable’s coding is confirmed.'),
 'retail-analysis':('Turn reported retail summaries into a readable business analysis.','Revision of supplied summary outputs for 51,290 records, 2011–2014.','A KPI summary, a comparison of mean and median sales, and an explanation of the distribution and the limits of the profit summaries.','Average sales and positive aggregate profit do not describe the performance of every record. Analysis by segment would require the original workbook.')}
 q,scope,output,lesson=briefs[p['slug']]
 return '<div class="case-brief"><h2>Project brief</h2>'+''.join('<div><h3>'+title+'</h3><p>'+e(text)+'</p></div>' for title,text in [('Question',q),('Analytical scope',scope),('Presented output',output),('Interpretation',lesson)])+'</div>'
def engagement():
 return section('engagement',heading('03 / Working together','Start with a clear scope.','Share the research question, available material and expected output. We can discuss whether the work is a good fit, agree on timing and define an appropriate scope.')+'<div class="principles"><article><h3>Define the assignment</h3><p>Agree deliverables, evidence, confidentiality and intended audience.</p></article><article><h3>Review a proposal</h3><p>Confirm fee, timeline, communication and included revisions before work begins.</p></article><article><h3>Begin with a pilot if useful</h3><p>A small paid pilot can provide a practical starting point for a larger assignment.</p></article></div><a class="text-link" href="/how-i-work/">How engagements work →</a>')
def profile():
 return section('professional-profile','<div class="profile-sheet"><h2>Asif Hussain</h2><p><strong>Economics Researcher | Research Consultant | Data Analyst</strong><br>Pakistan · Remote international collaboration</p><p><a href="mailto:'+e(D['email'])+'">'+e(D['email'])+'</a> · <a href="'+e(D['linkedin'])+'">LinkedIn</a></p><h3>Research profile</h3><p>'+e(D['bio'])+'</p><h3>Education</h3><p>MPhil Economics · Bahauddin Zakariya University · 2022–2024<br>BS Economics · University of Sargodha · 2017–2021</p>'+experience()+'<h3>Research background</h3><p>MPhil research on e-commerce, employment and inclusive growth across 20 developing countries, 2014–2023. The supplied CV documents fixed-effects, random-effects and GMM methods. Ongoing research collaboration with Dr Dragana Radicic, University of Lincoln, concerns Inclusive Growth Index development and determinants; this is not employment or institutional endorsement.</p><h3>Tools</h3><p>Primary professional tools: Stata and Microsoft Excel. Additional analytical experience and training: Power BI, SQL, R, Python and SPSS.</p><p><a href="/certifications/">Education and training details →</a></p><button type="button" class="btn outline" data-print>Print / Save Profile as PDF</button><p class="small">Browser-generated professional profile; private CV contacts and CGPA are omitted.</p></div>')
write(Path('profile'),'Professional Profile','Public-safe professional profile of Asif Hussain: economics education, research experience, methods and contact information.',pagehero('Professional Profile','Asif Hussain','Economics Researcher | Research Consultant | Data Analyst')+profile(),'About')
write(Path('.'),'Economics Research, Data Analytics & Consulting','Economic research, quantitative analysis and research quality review by Asif Hussain, based in Pakistan and working remotely.',hero()+capabilities()+featured()+qualifications_preview()+engagement()+cta(),'Home')
write(Path('about'),'About & Professional Experience','Asif Hussain’s economics education, remote Research Associate experience and independent research interests.',pagehero('About','An economist’s training.<br>A researcher’s care.','Economic research, quantitative interpretation and clear communication.')+about(),'About')
write(Path('services'),'Research & Consulting Services','Explore seven research, econometric, reporting, financial research, document-review and AI-evaluation services.',pagehero('Services','Careful research.<br>Useful analytical support.','Work begins with a clear question, appropriate evidence and an agreed scope.')+services()+B.paid(),'Services')
for s in D['services']:write(Path('services')/s['id'],s['name'],s['summary'],pagehero('Services',e(s['name']),e(s['summary']))+service_page(s),'Services')
write(Path('projects'),'Projects & Research Library','Three source-supported case studies in economic indicators, statistical interpretation and retail analysis.',pagehero('Projects & Research','Selected work.<br>Clear evidence.','A focused selection of analytical samples, with sources, methods and limitations in view.')+library(),'Projects & Research')
write(Path('ai-evaluation'),'AI Evaluation & Research Reviews','Evidence-to-claim auditing, research methodology review and AI-assisted document evaluation.',pagehero('AI Evaluation & Research Reviews','Read critically.<br>Review the evidence.','Research quality assurance for analytical reports, statistical interpretation and technical documentation.')+ai_page(),'AI Evaluation')
write(Path('certifications'),'Certifications & Education','Economics qualifications and a filterable professional-development gallery with supplied Google credential URLs.',pagehero('Certifications & Education','A foundation in economics.<br>A commitment to learning.','Education and professional development, with dates and evidence boundaries made clear.')+certifications(),'Certifications & Education')
write(Path('skills'),'Research Tools & Skills','Primary tools Stata and Excel, additional analytical experience, quantitative methods and documented training.',pagehero('Research Tools & Skills','Methods before software.<br>Tools for the question.','Capabilities described in context, without numerical ratings or inflated proficiency claims.')+skills(),'Research Tools & Skills')
write(Path('how-i-work'),'How I Work & Trial Projects','A five-stage research process, confidentiality principles, scoped trial tasks and paid collaboration formats.',pagehero('How I Work','A transparent process.<br>A clearly agreed result.','Define, source, analyse, validate and communicate.')+how(),'How I Work')
write(Path('contact'),'Contact & Project Enquiries','Discuss research assignments, contract opportunities or paid consulting with Asif Hussain through a clear email-based enquiry.',pagehero('Contact','Let’s work on<br>a useful question.','Describe your objective, evidence and expected output. We can agree a suitable next step.')+contact(),'Contact')
for p in P['projects']:write(Path('work')/p['slug'],p['title'],p['summary'],project_page(p),'Projects & Research')
(OUT/'assets/insights.json').write_text(json.dumps(D['south_asia']))
(OUT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+D['site_url']+'/sitemap.xml\n')
(OUT/'.nojekyll').write_text('')
urls=[D['site_url']+'/'+str(f.parent.relative_to(OUT)).strip('.').strip('/') for f in OUT.rglob('index.html')]
(OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+e(u.rstrip('/')+'/')+'</loc></url>' for u in urls)+'</urlset>')
print(f'Built {len(list(OUT.rglob("index.html")))} pages. Private PDFs excluded unless explicitly approved.')
